-- Fictional role fixture; management is separate from clinic original authority.
begin;
create function pg_temp.ca_assert(v boolean,m text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',m;end if;end$$;
select pg_temp.ca_assert(to_regprocedure('public.clinic_admin_membership_command(jsonb)')is not null,'clinic admin RPC absent');
insert into auth.users(id,email,email_confirmed_at,encrypted_password)values('c4600000-0000-4000-8000-000000000001','admin-c460@example.invalid',now(),'fixture-not-auth-login'),('c4600000-0000-4000-8000-000000000002','target-c460@example.invalid',now(),'fixture-not-auth-login');
insert into auth.sessions(id,user_id,created_at,updated_at)values('c4600000-0000-4000-8000-000000000011','c4600000-0000-4000-8000-000000000001',now(),now()),('c4600000-0000-4000-8000-000000000012','c4600000-0000-4000-8000-000000000002',now(),now());
insert into public.workspace_staff(user_id,role,display_name)values('c4600000-0000-4000-8000-000000000001','admin','Fictional admin c460');
insert into public.workspace_clinics(id,name)values('c4600000-0000-4000-8000-000000000021','Fictional clinic c460');
create temp table ca(k text primary key,p jsonb);grant all on ca to authenticated;
insert into ca values('grant','{"version":"clinic-admin-command-v1","op":"grant-existing","submissionId":"c4600000-0000-4000-8000-000000000031","clinicId":"c4600000-0000-4000-8000-000000000021","membershipId":"c4600000-0000-4000-8000-000000000041","userId":"c4600000-0000-4000-8000-000000000002","email":"target-c460@example.invalid","displayName":"Fictional uploader c460"}');
select set_config('request.jwt.claims','{"sub":"c4600000-0000-4000-8000-000000000001","session_id":"c4600000-0000-4000-8000-000000000011","exp":4102444800,"role":"authenticated","amr":[{"method":"password"}]}',true);set local role authenticated;
select pg_temp.ca_assert(public.clinic_admin_account_lookup(' TARGET-C460@example.invalid ')->>'status'='eligible','exact confirmed account lookup');
select pg_temp.ca_assert(public.clinic_admin_membership_command(p||'{"submissionId":"c4600000-0000-4000-8000-000000000039","email":"other@example.invalid"}')->>'reason'='account_unavailable','cannot adopt mismatched identity')from ca where k='grant';
select pg_temp.ca_assert(public.clinic_admin_membership_command(p)->>'status'='committed','grant existing confirmed account')from ca where k='grant';
select pg_temp.ca_assert(public.clinic_admin_membership_command(p)->>'status'='committed','exact grant replay')from ca where k='grant';
select pg_temp.ca_assert(public.clinic_admin_membership_command(p||'{"displayName":"changed"}')->>'reason'='conflict','same request changed payload')from ca where k='grant';
select pg_temp.ca_assert(jsonb_array_length(public.clinic_admin_memberships_page('c4600000-0000-4000-8000-000000000021',null,50)->'memberships')=1,'admin page exact membership');
do $$begin perform public.clinic_portal_identity('c4600000-0000-4000-8000-000000000021');raise exception 'management granted implicit clinic read';exception when insufficient_privilege then null;end$$;
insert into ca values('revoke','{"version":"clinic-admin-command-v1","op":"revoke","submissionId":"c4600000-0000-4000-8000-000000000032","clinicId":"c4600000-0000-4000-8000-000000000021","membershipId":"c4600000-0000-4000-8000-000000000041","expectedRevision":1}');
select pg_temp.ca_assert(public.clinic_admin_membership_command(p)->>'status'='committed','revoke explicit revision')from ca where k='revoke';
select pg_temp.ca_assert(public.clinic_admin_membership_command(p||'{"submissionId":"c4600000-0000-4000-8000-000000000033"}')->>'status'='stale','stale revoke denied')from ca where k='revoke';
insert into ca values('update','{"version":"clinic-admin-command-v1","op":"update","submissionId":"C4600000000040008000000000000034","clinicId":"c4600000-0000-4000-8000-000000000021","membershipId":"c4600000-0000-4000-8000-000000000041","expectedRevision":2,"displayName":"Fictional uploader c460","active":true}');
select pg_temp.ca_assert(public.clinic_admin_membership_refresh(p)#>>'{receipt,status}'='retired','refresh retires absent reactivation')from ca where k='update';
select pg_temp.ca_assert(public.clinic_admin_membership_command(p)->>'reason'='conflict','delayed reactivation fenced')from ca where k='update';
reset role;
select pg_temp.ca_assert((select not active and revision=2 from public.clinic_portal_memberships where id='c4600000-0000-4000-8000-000000000041'),'revocation retained');
select pg_temp.ca_assert(not exists(select 1 from public.workspace_staff where user_id='c4600000-0000-4000-8000-000000000002'),'grant never inserts global staff');
select set_config('request.jwt.claims','{"sub":"c4600000-0000-4000-8000-000000000002","session_id":"c4600000-0000-4000-8000-000000000012","exp":4102444800,"role":"authenticated","amr":[{"method":"password"}]}',true);set local role authenticated;
select pg_temp.ca_assert(public.clinic_admin_membership_command(p)->>'status'='access','ordinary clinic actor cannot manage')from ca where k='grant';
reset role;
select set_config('request.jwt.claims','{"sub":"c4600000-0000-4000-8000-000000000001","session_id":"c4600000-0000-4000-8000-000000000011","exp":4102444800,"role":"authenticated","amr":[{"method":"recovery"}]}',true);set local role authenticated;
select pg_temp.ca_assert(public.clinic_admin_membership_command(p)->>'status'='access','recovery admin cannot replay management')from ca where k='grant';
reset role;
select set_config('request.jwt.claims','{"sub":"c4600000-0000-4000-8000-000000000001","session_id":"c4600000-0000-4000-8000-000000000011","exp":1,"role":"authenticated","amr":[{"method":"password"}]}',true);set local role authenticated;
select pg_temp.ca_assert(public.clinic_admin_membership_command(p)->>'status'='access','expired admin cannot replay management')from ca where k='grant';
reset role;
delete from auth.sessions where id='c4600000-0000-4000-8000-000000000011';
select set_config('request.jwt.claims','{"sub":"c4600000-0000-4000-8000-000000000001","session_id":"c4600000-0000-4000-8000-000000000011","exp":4102444800,"role":"authenticated","amr":[{"method":"password"}]}',true);set local role authenticated;
select pg_temp.ca_assert(public.clinic_admin_membership_command(p)->>'status'='access','deleted admin SID cannot replay management')from ca where k='grant';
reset role;
select pg_temp.ca_assert(not has_table_privilege('authenticated','public.clinic_admin_commands','INSERT'),'no direct management receipts');
rollback;
